-sm-12">												<div class="form-group">													<label class="col-form-label search_title">Ngày</label>													<div class="search_input">														<div class="input-group input-append date" id="datePickerFromday">															<?php $fromday = (isset($get['fromday']) && ($get['fromday'] != '') ? $get['fromday'] : '');?>															<input type="text" class="form-control form-control-sm input-sm" name="fromday" value="<?php echo $fromday; ?>" />															<span class="input-group-addon add-on"><span class="glyphicon glyphicon-calendar"></span></span>														</div>													</div>												</div>											</div>											<div class="col-xl-2 col-lg-2 col-md-2 col-sm-12">												<div class="form-group">													<label class="col-form-label search_title">Đến ngày</label>													<div class="search_input">														<div class="input-group input-append date" id="datePickerToday">															<?php $today = (isset($get['today']) && ($get['today'] != '') ? $get['today'] : '');?>															<input type="text" class="form-control form-control-sm input-sm" name="today" value="<?php echo $today; ?>" />															<span class="input-group-addon add-on"><span class="glyphicon glyphicon-calendar"></span></span>														</div>													</div>												</div>											</div>											<div class="col-xl-2 col-lg-2 col-md-2 col-sm-12">												<label class="col-form-label search_title">Số dòng hiển thị</label>												<div class="search_input">													<select class="form-control form-control-sm input-sm" name="per_page">															<option value="0">Tất cả</option>															<?php																$records_in_page = 10;																$data_per_page = array();																for ($i = 1; $i <= 10; $i++) {																	$per_page = $i * $records_in_page;																	$data_per_page[$per_page] = $per_page;																}																echo get_option_select($data_per_page, isset($get['per_page']) ? $get['per_page'] : 10);															?>													</select>												</div>											</div>											<div class="col-xl-2 col-lg-2 col-md-2 col-sm-12">												<label class="col-form-label search_title"></label>												<div class="form-group search_action">														<button type="submit" class="btn btn-block btn-primary btn-sm">Xem</button>												</div>											</div>										</div>									</div>							</div>						</div>					</form>				</div>		</div>		<div class="card-content custom-card-table">			<div class="box-body" id="element_print">					<?php if (!empty($rows)): ?>							<form class="form-inline" name="main" method="post" action="<?php echo base_url($module_slug . '/' . 'cap-nhat'); ?>">									<div class="table-responsive">											<table class="table table-striped table-bordered table-hover">													<thead>															<tr>																	<th>Tên <?php echo $module_name; ?></th>																	<th class="text-right">Tổng số lượng</th>																	<th class="text-right">Tổng tiền</th>															</tr>													</thead>													<tbody>															<?php						$total_number = 0;						$total_quantity = 0;						if(isset($get['provider'])){							unset($get['provider']);						}						if(isset($get['per_page'])){							unset($get['per_page']);						}						foreach ($rows as $row):							$total_number_quantity = array_sum(array_column($row['purchase_voucher_details'], 'quantity'));							$total_number_monetized = array_sum(array_column($row['purchase_voucher_details'], 'monetized'));							$total_quantity += $total_number_quantity;							$total_number += $total_number_monetized;														?>																		<tr>																				<td>																						<a target="_blank" href="<?php echo (isset($get) && !empty($get)) ? site_url('bao-cao/nha-cung-cap-chi-tiet') . '?id=' . $row['id'] . '&' . http_build_query($get, '', "&") : site_url('bao-cao/nha-cung-cap-chi-tiet') . '?id=' . $row['id']; ?>"><?php echo $row['name']; ?></a>																				</td>																				<td class="text-right"><?php echo format_rice_en($total_number_quantity); ?></td>																				<td class="text-right"><?php echo format_rice_en($total_number_monetized); ?></td>																		</tr>																<?php endforeach;?>													</tbody>													<tfoot>															<tr>																	<td>																			Tổng cộng																	</td>																	<td class="text-right">																			<strong><?php echo format_rice_en($total_quantity); ?></strong>																	</td>							 <td class="text-right">																			<strong><?php echo format_rice_en($total_number); ?></strong>																	</td>															</tr>													</tfoot>											</table>									</div>							</form>					<?php else: ?>							<div class="callout callout-warning">									<h4>Thông báo!</h4>									<p><b>Không</b> có <?php echo $module_name; ?> nào!</p>							</div>					<?php endif;?>			</div>			<?php if (isset($pagination) && $pagination != ''): ?>					<div class="box-footer clearfix">						<nav class="box-pagination">							<?php echo $pagination; ?>						</nav>					</div>			<?php endif;?>		</div>	</div></div>